/*
 * The figures of "How it works", as generated by scripts/how-figures.mjs into how-figures.json (committed).
 * A figure its source does not hold is null; the page then leaves out what it would say.
 */
import data from "./how-figures.json";
import type { Lang } from "./i18n";

type Of = { of: number };
type SealedRun = { file: string; questions: number; literature: { in_full: number; asks: number } & Of; catalogue: { correct: number } & Of };

export type HowFigures = {
  run: {
    file: string;
    label: string;
    through: "host" | "development";
    questions: { all: number; catalogue: number; literature: number; out_of_scope: number };
    catalogue: { correct: number; supported: number } & Of;
    literature: { in_full: number; in_part: number; not: number; not_written: number; asks: number | null } & Of;
    out_of_scope: { no_answer: number } & Of;
    sentences: { removed: number; written: number };
    citations: { not_hold: number } & Of;
    cost: { mean: number; max: number } | null;
    page_found: { found: number; k: number; drafts: number } & Of | null;
    waits: { evidence: number; answer: number; answer_p95: number } | null;
  };
  issue_found: { first: number; three: number; es_first: number; es_of: number } & Of;
  full_text: { first: number; three: number; es_first: number; es_of: number } & Of;
  tried: {
    whole: { passages: number; answered: number } & Of;
    kept_answered: number;
    hybrid: { answered: number; vector: number } & Of;
    thinking_off: { cut: number } & Of;
    stronger: { model: string; served_model: string; in_full: [number, number]; served_in_full: [number, number]; usd: number; served_usd: number; times: number } & Of;
  };
  sealed: { questions: number; runs: SealedRun[] };
  limits: {
    per_minute: number;
    per_day: number;
    model_calls_a_day: number;
    question_chars: number;
    issues: number;
    passages: number;
    web_searches_a_month: number;
    vectors_in_memory: number;
    models: { writer: string; embedding: string };
  };
  versions: {
    langgraph: string;
    fastapi: string;
    python: string;
    next: string;
    react: string;
    typescript: string;
    playwright: string;
    pytest: string;
    tests: { python: number; python_files: number; browser: number; browser_files: number };
  };
  judges: {
    pages: { first: string; second: string; sample: number; same_grade: number; same_answers_or_not: number };
    answers: { second: string; answers: number; same_mark: number; kappa: number };
  };
  stores: {
    graph: { neo4j: string; issues: number; stamps: number; index: { type: string; similarity: string } };
    literature: { weaviate: string; objects: number; dimensions: number; index: { type: string; similarity: string; compression: string } };
  };
  points_a_question: [number, number];
  after_first_usd: number | null;
  spend_limit: { usd: number; month: string } | null;
  trace: {
    date: string;
    lang: Lang;
    after: Record<Lang, string>;
    asked: string;
    searched: string;
    caption: Record<Lang, string>;
    issues: { title: string; score: number; printer: string; source: number | null }[];
    answer: { text: string; sources: number[] }[];
    note: Record<Lang, string>;
  };
};

export const FIGURES = data as unknown as HowFigures;
